('fcfd8a99-62d3-4628-8d1d-e235397029b1','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_CENTRAL":"Central sólido en las coberturas, pero hay mejores opciones en el mercado. Seguir viendo","car_obs_central":"Central sólido en las coberturas, pero hay mejores opciones en el mercado. Seguir viendo"}'),
('00b79a57-68f8-4fdf-89ad-5cc38ff9952b','{"val_partido":"4. ALTA RELEVANCIA","car_obs_ARQUERO":"Arquero ágil de reacción para recomponerse, pero da muchos rebotes y para su edad no es un arquero diferencial o que mejore al actual arquero del club. Descarte.","car_obs_arquero":"Arquero ágil de reacción para recomponerse, pero da muchos rebotes y para su edad no es un arquero diferencial o que mejore al actual arquero del club. Descarte."}'),
('053db1c6-317d-4ad9-8eee-f34206897f53','{"val_partido":"5. MUY IMPORTANTE","valoracion":"2.DESCARTAR","car_obs_EXTREMO":"Fué el jugador más incisivo de su equipo el día de hoy, buscó siempre el duelo 1vs1 y en ocasiones salió airoso, casi siempre encara para afuera y tiene buen regate y algo de aceleración, pero por edad y en una posición que se necesita más dinámica para el fútbol ecuatoriano, es un perfil que hay que descartar.","car_obs_extremo":"Fué el jugador más incisivo de su equipo el día de hoy, buscó siempre el duelo 1vs1 y en ocasiones salió airoso, casi siempre encara para afuera y tiene buen regate y algo de aceleración, pero por edad y en una posición que se necesita más dinámica para el fútbol ecuatoriano, es un perfil que hay que descartar."}'),
